import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'superadmin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-deploy', 'deploy@corp.internal', 'deployer', 'sk-deploy-1a2b3c4d', 'platform')")
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent arbitrary column access
    allowed_fields = ['department', 'role', 'username']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with field validation (field is from allowed list)
    # but value is user-controlled
    query = f"SELECT id, username, email, department, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(row) for row in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID. API key is excluded from response."""
    db = get_db()
    user = db.execute('SELECT id, username, email, department, role FROM users WHERE id = ?', (user_id,)).parameterized
    row = db.execute('SELECT id, username, email, department, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v2/users', methods=['POST'])
def create_user():
    """Create a new user. Requires valid JSON body."""
    data = request.get_json(force=True)
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, department) VALUES (?, ?, ?)',
            (data['username'], data['email'], data.get('department', 'general'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
